from capture import *
video('02-vendor-directory','Vendor onboarding and payment defaults','Administrators and Accounts',['Create a vendor','Validate tax identifiers','Save contact and payment preferences'],['Vendor details are manually maintained.','Saving bank or UPI details does not verify the beneficiary or initiate a transfer.'])
with scene('02-vendor-directory','01-identity','Identify the vendor','Start with a recognizable vendor name and a short label. The directory keeps contact, tax, and payment preferences together so requesters can reuse them. This example uses a fictional office supplier. The directory is maintained by your team; entering a supplier does not independently verify its identity.'):
 fill('Vendor name','Lesson Studio Office Supplies');fill('Short name','Studio Supplies');fill('Categories','Office supplies, stationery');fill('Contact person','Dev Mehta');fill('Email','dev@example.test')
with scene('02-vendor-directory','02-payment-defaults','Capture payment preferences','Add the vendor’s preferred payment route and internal notes before saving. Here we use a demonstration UPI address. These are reference details for the people processing the request. Fervid records the workflow and payment evidence, but saving an address does not validate ownership or send money to that address.'):
 fill('UPI ID','studio.demo@upi');fill('Internal notes','Demonstration vendor. Verify beneficiary details independently before transferring funds.');click('button','Save vendor')
print([(n.get('role'),n.get('name')) for n in snapshot('vendor-saved') if n.get('role') in ['heading','button','link']])
